#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

bool isAnagram(string s, string t) {
    if (s.length() != t.length()) {
        return false;
    }

    unordered_map<char, int> count;

    for (char ch : s) {
        count[ch]++;
    }

    for (char ch : t) {
        count[ch]--;
    }

    for (auto &p : count) {
        if (p.second != 0) {
            return false;
        }
    }

    return true;
}

int main() {
    cout << boolalpha;

    cout << isAnagram("listen", "silent") << endl; // true
    cout << isAnagram("hello", "world") << endl;   // false

    return 0;
}

