public class Main {
    public static String removeAdjacentDuplicates(String s) {
        StringBuilder stack = new StringBuilder();

        for (char ch : s.toCharArray()) {
            if (stack.length() > 0 && stack.charAt(stack.length() - 1) == ch) {
                stack.deleteCharAt(stack.length() - 1);  // cancel out matching pair
            } else {
                stack.append(ch);
            }
        }

        return stack.toString();
    }

    public static void main(String[] args) {
        System.out.println(removeAdjacentDuplicates("abbaca")); // ca
        System.out.println(removeAdjacentDuplicates("azxxzy")); // ay
    }
}

