def remove_adjacent_duplicates(s):
    stack = []

    for ch in s:
        if stack and stack[-1] == ch:
            stack.pop()  # cancel out matching pair
        else:
            stack.append(ch)

    return "".join(stack)


if __name__ == "__main__":
    print(remove_adjacent_duplicates("abbaca"))  # ca
    print(remove_adjacent_duplicates("azxxzy"))  # ay
